				continue@__L2
			}
			var yCrown: Double = ((ctx!!.nodes)!!.crown_elev)!!.a!![ui.toInt()] - ((ctx!!.nodes)!!.invert_elev)!!.a!![ui.toInt()]
			if ((((ctx!!.nodes)!!.depth)!!.a!![ui.toInt()] + F_constants.FUDGE) >= yCrown) {
				i++
				continue@__L2
			}
