	open fun buildVirtualJunctionPairs(ctx: SimulationContext?) {
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		this.vjunc_!!.clear()
		this.vj_pair_n1_!!.assign_ul_T(this.n_links_.toLong(), -1)
