			}
			var __r1: BooleanArray? = booleanArrayOf(true, false)
			var __i2: Long = 0L
			var __i2_n: Long = (__r1!!.size).toLong()
			__L3@ while (__i2 < __i2_n) {
				var at_node1: Boolean = __r1!![__i2.toInt()]
				var n: Int = (if (at_node1) cpp.RefI.Arr((links!!.node1)!!.a, uj.toInt()) else cpp.RefI.Arr((links!!.node2)!!.a, uj.toInt()))!!.get()
				if ((n < 0) || (n >= this.n_nodes_)) {
					__i2++
					continue@__L3
				}
				var r: Int = row_of_node!!.a!![n.toLong().toInt()]
				if (r < 0) {
					__i2++
					continue@__L3
				}
				var p_2: dynwave_DWSolver_VJuncPair? = this.vjunc_!!.a!![r.toLong().toInt()] as dynwave_DWSolver_VJuncPair?
				if (p_2!!.link_a < 0) {
					p_2!!.link_a = j
				} else {
					if (p_2!!.link_b < 0) {
						p_2!!.link_b = j
					}
				}
				if (at_node1) {
					this.vj_pair_n1_!!.a!![uj.toInt()] = r
				} else {
					this.vj_pair_n2_!!.a!![uj.toInt()] = r
				}
				__i2++
			}
			j++
		}
		var __r3: cpp.Vec<dynwave_DWSolver_VJuncPair?>? = this.vjunc_
		var __i4: Long = 0L
		var __i4_n: Long = (__r3!!.n).toLong()
		__L4@ while (__i4 < __i4_n) {
			var p_3: dynwave_DWSolver_VJuncPair? = (__r3!!.a)!![__i4.toInt()] as dynwave_DWSolver_VJuncPair?
			if ((p_3!!.link_a < 0) || (p_3!!.link_b < 0)) {
				__i4++
				continue@__L4
			}
			var ua: Long = (p_3!!.link_a).toLong()
			var ub: Long = (p_3!!.link_b).toLong()
			if (((links!!.node2)!!.a!![ua.toInt()] == p_3!!.node) && ((links!!.node1)!!.a!![ub.toInt()] == p_3!!.node)) {
				p_3!!.up_link = p_3!!.link_a
				p_3!!.dn_link = p_3!!.link_b
				p_3!!.through = (1).toByte()
			} else {
				if (((links!!.node2)!!.a!![ub.toInt()] == p_3!!.node) && ((links!!.node1)!!.a!![ua.toInt()] == p_3!!.node)) {
					p_3!!.up_link = p_3!!.link_b
					p_3!!.dn_link = p_3!!.link_a
					p_3!!.through = (1).toByte()
				} else {
