		}
	}

	open fun vjPrepareIteration(ctx: SimulationContext?, dt: Double) {
		var links: LinkData? = ctx!!.links
		var full_momentum: Boolean = (ctx!!.options)!!.virtual_junction_momentum == 1
		var __r1: cpp.Vec<dynwave_DWSolver_VJuncPair?>? = this.vjunc_
		var __i2: Long = 0L
		var __i2_n: Long = (__r1!!.n).toLong()
		__L1@ while (__i2 < __i2_n) {
			var p: dynwave_DWSolver_VJuncPair? = (__r1!!.a)!![__i2.toInt()] as dynwave_DWSolver_VJuncPair?
			p!!.active = (0).toByte()
			p!!.dirn = (0).toByte()
			p!!.dq4j = 0.0
			if (((!(((p!!.through).toInt() and 0xFF) != 0)) || (p!!.up_link < 0)) || (p!!.dn_link < 0)) {
				__i2++
				continue@__L1
			}
			if (((p!!.node >= 0) && (java.lang.Long.compareUnsigned((p!!.node).toLong(), ((ctx!!.nodes)!!.is_inlet)!!.size()) < 0)) && (((((ctx!!.nodes)!!.is_inlet)!!.a!![(p!!.node).toLong().toInt()]).toInt() and 0xFF) != 0)) {
				__i2++
				continue@__L1
			}
			var uu: Long = (p!!.up_link).toLong()
			var ud: Long = (p!!.dn_link).toLong()
			var ucu: Long = (this.tile_uj_to_ci_!!.a!![uu.toInt()]).toLong()
			var ucd: Long = (this.tile_uj_to_ci_!!.a!![ud.toInt()]).toLong()
			var aj: Double = this.area2_!!.a!![uu.toInt()]
			var wj: Double = this.width2_!!.a!![uu.toInt()]
			if (aj <= F_constants.FUDGE) {
				__i2++
				continue@__L1
			}
			var ajFull: Double = (links!!.xsect_a_full)!!.a!![uu.toInt()]
			var qU: Double = (links!!.flow)!!.a!![uu.toInt()] / this.tile_barrels_d_!!.a!![ucu.toInt()]
			var qD: Double = (links!!.flow)!!.a!![ud.toInt()] / this.tile_barrels_d_!!.a!![ucd.toInt()]
			var vj: Double = (0.5 * (qU + qD)) / F_dynwave.conveyArea_DynamicWave(aj, ajFull)
			if (cpp.SysMath.Abs_d(vj) > F_constants.MAX_VELOCITY) {
				vj = if (vj > 0.0) F_constants.MAX_VELOCITY else -F_constants.MAX_VELOCITY
			}
			var dh: Double = if (wj > F_constants.FUDGE) aj / wj else 0.0
			var frj: Double = if (dh > 0.0) cpp.SysMath.Abs_d(vj) / cpp.SysMath.Sqrt_d(F_constants.GRAVITY * dh) else 0.0
			p!!.sigma_j = cpp.M.max_d_d(0.0, cpp.M.min_d_d(1.0, 2.0 * (1.0 - frj)))
			p!!.a_up_mid = F_dynwave.conveyArea_DynamicWave(this.area_mid_!!.a!![uu.toInt()], ajFull)
			p!!.r_up_mid = this.hrad_mid_!!.a!![uu.toInt()]
			p!!.active = (1).toByte()
			if (((qU >= 0.0) && (qD >= 0.0)) && ((qU + qD) > 0.0)) {
				p!!.dirn = (1).toByte()
			} else {
				if (((qU <= 0.0) && (qD <= 0.0)) && ((qU + qD) < 0.0)) {
					p!!.dirn = (-1).toByte()
				}
			}
			if ((full_momentum && (p!!.lambda > 0.0)) && ((p!!.dirn).toInt() != 0)) {
				var aMu: Double = cpp.M.max_d_d(this.area_mid_!!.a!![uu.toInt()], F_constants.FUDGE)
				var aMd: Double = cpp.M.max_d_d(this.area_mid_!!.a!![ud.toInt()], F_constants.FUDGE)
				var vu: Double = qU / aMu
				var vd: Double = qD / aMd
				p!!.dq4j = ((dt * p!!.sigma_j) * (((vd * vd) * aMd) - ((vu * vu) * aMu))) / p!!.lambda
			}
