			if (((!(((p_2!!.through).toInt() and 0xFF) != 0)) || (p_2!!.up_link < 0)) || (p_2!!.dn_link < 0)) {
				r++
				continue@__L2
			}
			var uu: Long = (p_2!!.up_link).toLong()
			var ud: Long = (p_2!!.dn_link).toLong()
			var aU: Double = this.area2_!!.a!![uu.toInt()]
			var aD: Double = this.area1_!!.a!![ud.toInt()]
			if ((aU <= F_constants.FUDGE) || (aD <= F_constants.FUDGE)) {
				r++
				continue@__L2
			}
			var ucu: Long = (this.tile_uj_to_ci_!!.a!![uu.toInt()]).toLong()
			var ucd: Long = (this.tile_uj_to_ci_!!.a!![ud.toInt()]).toLong()
			var qU: Double = (links!!.flow)!!.a!![uu.toInt()] / this.tile_barrels_d_!!.a!![ucu.toInt()]
			var qD: Double = (links!!.flow)!!.a!![ud.toInt()] / this.tile_barrels_d_!!.a!![ucd.toInt()]
			var flux: Double = ((qU * qU) / aU) - ((qD * qD) / aD)
