			p_2!!.resid_sum += aR
			p_2!!.resid_n++
			(d!!.resid_max)!!.a!![r.toInt()] = p_2!!.resid_max
			(d!!.resid_sum)!!.a!![r.toInt()] = p_2!!.resid_sum
			(d!!.resid_n)!!.a!![r.toInt()] = p_2!!.resid_n
