		var nodes: NodeData? = ctx!!.nodes
		if (!dynwave_DWSolver.S_mask_disabled_19_done) {
			dynwave_DWSolver.S_mask_disabled_19 = cpp.CPtr.op_Ne(cpp.R.getenv(cpp.R.Lit("SWMM_DISABLE_BYPASS_MASK")), cpp.CPtr.ZERO)
			dynwave_DWSolver.S_mask_disabled_19_done = true
		}
		this.groups_!!.setBypassMask(if (!dynwave_DWSolver.S_mask_disabled_19) cpp.CPtr.from_Ptruc(this.bypassed_!!.data()) else cpp.CPtr.ZERO)
		var slot_mode: Boolean = (this.surcharge_method == dynwave_SurchargeMethod.SLOT) || (this.surcharge_method == dynwave_SurchargeMethod.DYNAMIC_SLOT)
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var uci: Long = ci.toLong()
			var j: Int = this.tile_uj_!!.a!![uci.toInt()]
			var uj: Long = j.toLong()
			if (((this.bypassed_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				ci++
				continue@__L1
			}
			var un1: Long = (this.tile_n1_!!.a!![uci.toInt()]).toLong()
			var un2: Long = (this.tile_n2_!!.a!![uci.toInt()]).toLong()
			var inv1: Double = this.tile_inv1_elev_!!.a!![uci.toInt()]
			var inv2: Double = this.tile_inv2_elev_!!.a!![uci.toInt()]
			var z1: Double = inv1 + this.tile_z1_off_!!.a!![uci.toInt()]
			var z2: Double = inv2 + this.tile_z2_off_!!.a!![uci.toInt()]
			var h1: Double = cpp.M.max_d_d(F_lidnode.portDepth(ctx, un1.toInt(), this.tile_z1_off_!!.a!![uci.toInt()]) + inv1, z1)
			var h2: Double = cpp.M.max_d_d(F_lidnode.portDepth(ctx, un2.toInt(), this.tile_z2_off_!!.a!![uci.toInt()]) + inv2, z2)
			var y1: Double = cpp.M.max_d_d(h1 - z1, F_constants.FUDGE)
			var y2: Double = cpp.M.max_d_d(h2 - z2, F_constants.FUDGE)
			var yf: Double = this.tile_y_full_!!.a!![uci.toInt()]
			if (!slot_mode) {
				y1 = cpp.M.min_d_d(y1, yf)
				y2 = cpp.M.min_d_d(y2, yf)
			}
			var yMid: Double = 0.5 * (y1 + y2)
			this.depth1_!!.a!![uj.toInt()] = y1
			this.depth2_!!.a!![uj.toInt()] = y2
			this.depth_mid_!!.a!![uj.toInt()] = yMid
			this.h1_!!.a!![uj.toInt()] = h1
			this.h2_!!.a!![uj.toInt()] = h2
			this.fasnh_!!.a!![uj.toInt()] = 1.0
			if (!slot_mode) {
				var bs: Int = this.tile_xsect_batch_shape_!!.a!![uci.toInt()]
				var is_open: Boolean = F_xsect.isOpen(bs)
				var yCap: Double = if ((!is_open) && (yf > 0.0)) F_constants.EXTRAN_CROWN_CUTOFF * yf else 1E+30
				this.wcap_d1_!!.a!![uj.toInt()] = cpp.M.min_d_d(y1, yCap)
				this.wcap_d2_!!.a!![uj.toInt()] = cpp.M.min_d_d(y2, yCap)
				this.wcap_dm_!!.a!![uj.toInt()] = cpp.M.min_d_d(yMid, yCap)
			}
			ci++
		}
		var b_tid: Int = 0
		var b_nth: Int = 1
		if (!slot_mode) {
			this.groups_!!.computeWidthsTripleTeam(this.wcap_d1_!!.data(), this.wcap_d2_!!.data(), this.wcap_dm_!!.data(), this.width1_!!.data(), this.width2_!!.data(), this.width_mid_!!.data(), this.n_links_, b_tid, b_nth)
		} else {
			this.groups_!!.computeWidthsTripleTeam(this.depth1_!!.data(), this.depth2_!!.data(), this.depth_mid_!!.data(), this.width1_!!.data(), this.width2_!!.data(), this.width_mid_!!.data(), this.n_links_, b_tid, b_nth)
		}
		if (slot_mode) {
			var ci_2: Int = 0
			__L2@ while (ci_2 < this.n_conduits_) {
				var uci_2: Long = ci_2.toLong()
				var uj_2: Long = (this.tile_uj_!!.a!![uci_2.toInt()]).toLong()
				var yf_2: Double = this.tile_y_full_!!.a!![uci_2.toInt()]
				var wm: Double = this.tile_w_max_!!.a!![uci_2.toInt()]
				var shape: Short = this.tile_shape_!!.a!![uci_2.toInt()]
				var ws: Double = this.getSlotWidth(this.depth1_!!.a!![uj_2.toInt()], yf_2, wm, shape)
				if (ws > 0.0) {
					this.width1_!!.a!![uj_2.toInt()] = ws
				}
				ws = this.getSlotWidth(this.depth2_!!.a!![uj_2.toInt()], yf_2, wm, shape)
				if (ws > 0.0) {
					this.width2_!!.a!![uj_2.toInt()] = ws
				}
				ws = this.getSlotWidth(this.depth_mid_!!.a!![uj_2.toInt()], yf_2, wm, shape)
				if (ws > 0.0) {
					this.width_mid_!!.a!![uj_2.toInt()] = ws
				}
				ci_2++
			}
		}
		var ci_3: Int = 0
		__L3@ while (ci_3 < this.n_conduits_) {
			var uci_3: Long = ci_3.toLong()
			var j_2: Int = this.tile_uj_!!.a!![uci_3.toInt()]
			var uj_3: Long = j_2.toLong()
			if (((this.bypassed_!!.a!![uj_3.toInt()]).toInt() and 0xFF) != 0) {
				ci_3++
				continue@__L3
			}
			var un1_2: Long = (this.tile_n1_!!.a!![uci_3.toInt()]).toLong()
			var un2_2: Long = (this.tile_n2_!!.a!![uci_3.toInt()]).toLong()
			var yf_3: Double = this.tile_y_full_!!.a!![uci_3.toInt()]
			var z1_off: Double = this.tile_z1_off_!!.a!![uci_3.toInt()]
			var z2_off: Double = this.tile_z2_off_!!.a!![uci_3.toInt()]
			var beta_j: Double = this.tile_beta_!!.a!![uci_3.toInt()]
			var qmax_j: Double = this.tile_q_max_!!.a!![uci_3.toInt()]
			var inv1_2: Double = this.tile_inv1_elev_!!.a!![uci_3.toInt()]
			var inv2_2: Double = this.tile_inv2_elev_!!.a!![uci_3.toInt()]
			var y1_2: Double = this.depth1_!!.a!![uj_3.toInt()]
			var y2_2: Double = this.depth2_!!.a!![uj_3.toInt()]
			var h1_2: Double = this.h1_!!.a!![uj_3.toInt()]
			var h2_2: Double = this.h2_!!.a!![uj_3.toInt()]
			var length: Double = this.tile_length_!!.a!![uci_3.toInt()]
			var surfArea1: Double = 0.0
			var surfArea2: Double = 0.0
			var fc: Byte = FlowClass.SUBCRITICAL
			var fasnh: Double = 1.0
			var cached_yN: Double = 0.0
			var cached_yC: Double = 0.0
			var cached_xs: XSectParams? = XSectParams()
			var xs_built: cpp.RefZ.Cell = cpp.RefZ.Cell(false)
			var xs_ref: FN103? = FN103 __lam4@{ 
				if (!xs_built.v) {
					cached_xs!!.MoveFrom(F_dynwave.buildXSP_DynamicWave(ctx, uj_3))
					xs_built.v = true
				}
				return@__lam4 cached_xs
			}
			var both_full: Boolean = ((if (y1_2 >= yf_3) 1 else 0) and (if (y2_2 >= yf_3) 1 else 0)) != 0
			var both_wet: Boolean = ((if (y1_2 > F_constants.FUDGE) 1 else 0) and (if (y2_2 > F_constants.FUDGE) 1 else 0)) != 0
			var both_dry: Boolean = ((if (y1_2 <= F_constants.FUDGE) 1 else 0) and (if (y2_2 <= F_constants.FUDGE) 1 else 0)) != 0
			var up_dry_only: Boolean = ((if (y1_2 <= F_constants.FUDGE) 1 else 0) and (if (y2_2 > F_constants.FUDGE) 1 else 0)) != 0
			if (both_full) {
				fc = FlowClass.SUBCRITICAL
			} else {
				if (both_dry) {
					fc = FlowClass.DRY
				} else {
					if (!(((this.tile_has_offset_!!.a!![uci_3.toInt()]).toInt() and 0xFF) != 0)) {
						if (up_dry_only) {
							if (h2_2 < inv1_2) {
								fc = FlowClass.UP_DRY
							}
						} else {
							if (!both_wet) {
								if (h1_2 < inv2_2) {
									fc = FlowClass.DN_DRY
								}
							}
						}
					} else {
						var z1_off_eff: Double = z1_off
						var z2_off_eff: Double = z2_off
						if ((nodes!!.type)!!.a!![un1_2.toInt()] == NodeType.OUTFALL) {
							z1_off_eff = cpp.M.max_d_d(0.0, z1_off_eff - (nodes!!.depth)!!.a!![un1_2.toInt()])
						}
						if ((nodes!!.type)!!.a!![un2_2.toInt()] == NodeType.OUTFALL) {
							z2_off_eff = cpp.M.max_d_d(0.0, z2_off_eff - (nodes!!.depth)!!.a!![un2_2.toInt()])
						}
						var q: Double = cpp.SysMath.Abs_d(this.q1_!!.a!![uj_3.toInt()])
						if (both_wet) {
							if (this.q1_!!.a!![uj_3.toInt()] < 0.0) {
								if (z1_off_eff > 0.0) {
									var xs: XSectParams? = xs_ref!!.invoke()
									cached_yN = F_dynwave.computeYnorm_DynamicWave(xs, beta_j, qmax_j, q)
									cached_yC = F_xsect.getYcrit(xs, q)
									var ycMin: Double = cpp.M.min_d_d(cached_yN, cached_yC)
									if (y1_2 < ycMin) {
										fc = FlowClass.UP_CRITICAL
									}
								}
							} else {
								if (z2_off_eff > 0.0) {
									var xs_2: XSectParams? = xs_ref!!.invoke()
									cached_yN = F_dynwave.computeYnorm_DynamicWave(xs_2, beta_j, qmax_j, q)
									cached_yC = F_xsect.getYcrit(xs_2, q)
									var ycMin_2: Double = cpp.M.min_d_d(cached_yN, cached_yC)
									var ycMax: Double = cpp.M.max_d_d(cached_yN, cached_yC)
									if (y2_2 < ycMin_2) {
										fc = FlowClass.DN_CRITICAL
									} else {
										if (y2_2 < ycMax) {
											if ((ycMax - ycMin_2) < F_constants.FUDGE) {
												fasnh = 0.0
											} else {
												fasnh = (ycMax - y2_2) / (ycMax - ycMin_2)
											}
										}
									}
								}
							}
						} else {
							if (up_dry_only) {
								var z1_elev: Double = inv1_2 + z1_off
								if (h2_2 < z1_elev) {
									fc = FlowClass.UP_DRY
								} else {
									if (z1_off_eff > 0.0) {
										var xs_3: XSectParams? = xs_ref!!.invoke()
										cached_yN = F_dynwave.computeYnorm_DynamicWave(xs_3, beta_j, qmax_j, q)
										cached_yC = F_xsect.getYcrit(xs_3, q)
										fc = FlowClass.UP_CRITICAL
									}
								}
							} else {
								var z2_elev: Double = inv2_2 + z2_off
								if (h1_2 < z2_elev) {
									fc = FlowClass.DN_DRY
								} else {
									if (z2_off_eff > 0.0) {
										var xs_4: XSectParams? = xs_ref!!.invoke()
										cached_yN = F_dynwave.computeYnorm_DynamicWave(xs_4, beta_j, qmax_j, q)
										cached_yC = F_xsect.getYcrit(xs_4, q)
										fc = FlowClass.DN_CRITICAL
									}
								}
							}
						}
					}
				}
			}
			__sw5@ do {
				when (fc) {
					(3).toByte() -> {
						var w1: Double = this.width1_!!.a!![uj_3.toInt()]
						var wM: Double = this.width_mid_!!.a!![uj_3.toInt()]
						var w2: Double = this.width2_!!.a!![uj_3.toInt()]
						surfArea1 = ((w1 + wM) * length) / 4.0
						surfArea2 = (((wM + w2) * length) / 4.0) * fasnh
						break@__sw5
					}
					(5).toByte() -> {
						y1_2 = cached_yC
						if (cached_yN < cached_yC) {
							y1_2 = cached_yN
						}
						y1_2 = cpp.M.max_d_d(y1_2, F_constants.FUDGE)
						var z1_elev_2: Double = inv1_2 + z1_off
						h1_2 = z1_elev_2 + y1_2
						var yMid_2: Double = cpp.M.max_d_d(0.5 * (y1_2 + y2_2), F_constants.FUDGE)
						var w2_2: Double = this.width2_!!.a!![uj_3.toInt()]
						var xs_5: XSectParams? = xs_ref!!.invoke()
						var wM_2: Double = F_xsect.getWofY(xs_5, yMid_2)
						var wMsa: Double = 0.0
						var wSlotM: Double = this.getSlotWidth(yMid_2, yf_3, this.tile_w_max_!!.a!![uci_3.toInt()], this.tile_shape_!!.a!![uci_3.toInt()])
						if (wSlotM > 0.0) {
							wMsa = wSlotM
						} else {
							if (((yMid_2 / yf_3) >= this.getCrownCutoff()) && (!F_xsect.isOpen(this.tile_xsect_batch_shape_!!.a!![uci_3.toInt()]))) {
								wMsa = F_xsect.getWofY(xs_5, this.getCrownCutoff() * yf_3)
							} else {
								wMsa = wM_2
							}
						}
						surfArea2 = ((wMsa + w2_2) * length) * 0.5
						this.depth1_!!.a!![uj_3.toInt()] = y1_2
						this.depth_mid_!!.a!![uj_3.toInt()] = yMid_2
						this.width_mid_!!.a!![uj_3.toInt()] = wM_2
						this.h1_!!.a!![uj_3.toInt()] = h1_2
						break@__sw5
					}
					(6).toByte() -> {
						y2_2 = cached_yC
						if (cached_yN < cached_yC) {
							y2_2 = cached_yN
						}
						y2_2 = cpp.M.max_d_d(y2_2, F_constants.FUDGE)
						var z2_elev_2: Double = inv2_2 + z2_off
						h2_2 = z2_elev_2 + y2_2
						var yMid_3: Double = cpp.M.max_d_d(0.5 * (y1_2 + y2_2), F_constants.FUDGE)
						var w1_2: Double = this.width1_!!.a!![uj_3.toInt()]
						var xs_6: XSectParams? = xs_ref!!.invoke()
						var wM_3: Double = F_xsect.getWofY(xs_6, yMid_3)
						var wMsa_2: Double = 0.0
						var wSlotM_2: Double = this.getSlotWidth(yMid_3, yf_3, this.tile_w_max_!!.a!![uci_3.toInt()], this.tile_shape_!!.a!![uci_3.toInt()])
						if (wSlotM_2 > 0.0) {
							wMsa_2 = wSlotM_2
						} else {
							if (((yMid_3 / yf_3) >= this.getCrownCutoff()) && (!F_xsect.isOpen(this.tile_xsect_batch_shape_!!.a!![uci_3.toInt()]))) {
								wMsa_2 = F_xsect.getWofY(xs_6, this.getCrownCutoff() * yf_3)
							} else {
								wMsa_2 = wM_3
							}
						}
						surfArea1 = ((w1_2 + wMsa_2) * length) * 0.5
						this.depth2_!!.a!![uj_3.toInt()] = y2_2
						this.depth_mid_!!.a!![uj_3.toInt()] = yMid_3
						this.width_mid_!!.a!![uj_3.toInt()] = wM_3
						this.h2_!!.a!![uj_3.toInt()] = h2_2
						break@__sw5
					}
					(1).toByte() -> {
						y1_2 = F_constants.FUDGE
						var yMid_4: Double = cpp.M.max_d_d(0.5 * (F_constants.FUDGE + y2_2), F_constants.FUDGE)
						var w1_3: Double = this.width1_!!.a!![uj_3.toInt()]
						var w2_3: Double = this.width2_!!.a!![uj_3.toInt()]
						var wM_4: Double = this.width_mid_!!.a!![uj_3.toInt()]
						surfArea2 = ((wM_4 + w2_3) * length) / 4.0
						if (z1_off <= 0.0) {
							surfArea1 = ((w1_3 + wM_4) * length) / 4.0
						}
						this.depth1_!!.a!![uj_3.toInt()] = F_constants.FUDGE
						this.depth_mid_!!.a!![uj_3.toInt()] = yMid_4
						var xs_7: XSectParams? = xs_ref!!.invoke()
						this.width_mid_!!.a!![uj_3.toInt()] = F_xsect.getWofY(xs_7, yMid_4)
						break@__sw5
					}
					(2).toByte() -> {
						y2_2 = F_constants.FUDGE
						var yMid_5: Double = cpp.M.max_d_d(0.5 * (y1_2 + F_constants.FUDGE), F_constants.FUDGE)
						var w1_4: Double = this.width1_!!.a!![uj_3.toInt()]
						var w2_4: Double = this.width2_!!.a!![uj_3.toInt()]
						var wM_5: Double = this.width_mid_!!.a!![uj_3.toInt()]
						surfArea1 = ((wM_5 + w1_4) * length) / 4.0
						if (z2_off <= 0.0) {
							surfArea2 = ((w2_4 + wM_5) * length) / 4.0
						}
						this.depth2_!!.a!![uj_3.toInt()] = F_constants.FUDGE
						this.depth_mid_!!.a!![uj_3.toInt()] = yMid_5
						var xs_8: XSectParams? = xs_ref!!.invoke()
						this.width_mid_!!.a!![uj_3.toInt()] = F_xsect.getWofY(xs_8, yMid_5)
						break@__sw5
					}
					(0).toByte() -> {
						surfArea1 = (F_constants.FUDGE * length) / 2.0
						surfArea2 = surfArea1
						break@__sw5
					}
					else -> {
						break@__sw5
					}
				}
			} while (false)
			this.surf_area1_!!.a!![uj_3.toInt()] = surfArea1
			this.surf_area2_!!.a!![uj_3.toInt()] = surfArea2
			this.fasnh_!!.a!![uj_3.toInt()] = fasnh
			(links!!.flow_class)!!.a!![uj_3.toInt()] = fc
			ci_3++
		}
		var p_d1: cpp.PtrD? = this.depth1_!!.data()
		var p_d2: cpp.PtrD? = this.depth2_!!.data()
		var p_dm: cpp.PtrD? = this.depth_mid_!!.data()
		var p_a1: cpp.PtrD? = this.area1_!!.data()
		var p_a2: cpp.PtrD? = this.area2_!!.data()
		var p_am: cpp.PtrD? = this.area_mid_!!.data()
		var p_hm: cpp.PtrD? = this.hrad_mid_!!.data()
		var p_h1: cpp.PtrD? = this.hrad1_!!.data()
		var p_wm: cpp.PtrD? = this.width_mid_!!.data()
		var d_tid: Int = 0
		var d_nth: Int = 1
		this.groups_!!.computeAreaHydRadTripleTeam(p_d1, p_d2, p_dm, p_a1, p_a2, p_am, p_h1, p_hm, this.n_links_, d_tid, d_nth)
		if (this.surcharge_method == dynwave_SurchargeMethod.DYNAMIC_SLOT) {
			this.applyDPSGeometry(ctx)
		} else {
			if (this.surcharge_method == dynwave_SurchargeMethod.TPA) {
				this.applyTpaGeometry(ctx)
			}
		}
	}

	open fun recomputeConduitLossOne(ctx: SimulationContext?, dt: Double, ci: Int) {
		var links: LinkData? = ctx!!.links
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var evap: Double = this.evap_rate
		var uci: Long = ci.toLong()
		var uj: Int = this.conduit_idx_!!.a!![uci.toInt()]
		var u: Long = uj.toLong()
		var ucr: Long = (this.tile_crow_!!.a!![uci.toInt()]).toLong()
		var fc: Byte = (links!!.flow_class)!!.a!![u.toInt()]
		if ((((((fc == FlowClass.DRY) || (fc == FlowClass.UP_DRY)) || (fc == FlowClass.DN_DRY)) || (this.area_mid_!!.a!![u.toInt()] <= F_constants.FUDGE)) || (((this.tile_is_closed_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0)) || ((links!!.setting)!!.a!![u.toInt()] == 0.0)) {
			(CD!!.evap_loss_rate)!!.a!![ucr.toInt()] = 0.0
			(CD!!.seep_loss_rate)!!.a!![ucr.toInt()] = 0.0
			return
		}
		var depth: Double = 0.5 * ((links!!.old_depth)!!.a!![u.toInt()] + (links!!.depth)!!.a!![u.toInt()])
		var evap_loss: Double = 0.0
		var seep_loss: cpp.RefD.Cell = cpp.RefD.Cell(0.0)
		if (depth > F_constants.FUDGE) {
			var length: Double = (CD!!.true_length)!!.a!![ucr.toInt()]
			if (length <= 0.0) {
				length = (CD!!.length)!!.a!![ucr.toInt()]
			}
			if (length <= 0.0) {
				length = (CD!!.mod_length)!!.a!![ucr.toInt()]
			}
			var shape: Int = (links!!.xsect_batch_shape)!!.a!![u.toInt()]
			var gw_two_way: Boolean = (!((CD!!.gw_coupled)!!.empty())) && ((((CD!!.gw_coupled)!!.a!![ucr.toInt()]).toInt() and 0xFF) != 0)
			var k_seep: Double = (if (gw_two_way) cpp.RefD.Arr((CD!!.gw_kc)!!.a, ucr.toInt()) else cpp.RefD.Arr((CD!!.seep_rate)!!.a, ucr.toInt()))!!.get()
			var wantEvap: Boolean = F_xsect.isOpen(shape) && (evap > 0.0)
			var wantSeep: Boolean = k_seep > 0.0
			if (wantEvap || wantSeep) {
				var xs: XSectParams? = F_dynwave.buildXSP_DynamicWave(ctx, u)
				if (wantEvap) {
					var topWidth: Double = F_xsect.getWofY(xs, depth)
					evap_loss = (topWidth * length) * evap
				}
				if (wantSeep) {
					var d_seep: Double = depth
					if ((shape != 3) && (d_seep >= xs!!.yw_max)) {
						d_seep = xs!!.yw_max
					}
					var width: Double = if (shape == 3) xs!!.w_max else F_xsect.getWofY(xs, d_seep)
					seep_loss.v = (k_seep * width) * length
					seep_loss.v *= (ctx!!.climate_state)!!.infil_factor
					if (gw_two_way) {
						seep_loss.v *= F_hydraulics.aquiferSeepFactor(depth, (CD!!.gw_head_rel)!!.a!![ucr.toInt()], (CD!!.gw_dc)!!.a!![ucr.toInt()])
						seep_loss.v = F_hydraulics.capAquiferGain(seep_loss.v, (CD!!.gw_gain_max)!!.a!![ucr.toInt()])
					}
				}
			}
			var total: Double = evap_loss + cpp.M.max_d_d(seep_loss.v, 0.0)
			if (total > 0.0) {
				var q: Double = (links!!.volume)!!.a!![u.toInt()] / (dt * ((CD!!.barrels)!!.a!![ucr.toInt()]).toDouble())
				if (total > q) {
					evap_loss = (evap_loss * q) / total
					if (seep_loss.v > 0.0) {
						seep_loss.v = (seep_loss.v * q) / total
					}
				}
			}
		}
		F_hydraulics.applySeepageForcing(ctx, u, seep_loss)
		(CD!!.evap_loss_rate)!!.a!![ucr.toInt()] = evap_loss
		(CD!!.seep_loss_rate)!!.a!![ucr.toInt()] = seep_loss.v
	}

	open fun limitConduitLosses(ctx: SimulationContext?, dt: Double) {
		var nodes: NodeData? = ctx!!.nodes
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var adjustable: FN104? = FN104 __lam1@{ j, r ->
				var modes: cpp.VecB? = (ctx!!.forcing)!!.link_seepage_mode
				return@__lam1 ((java.lang.Long.compareUnsigned(j.toLong(), modes!!.size()) >= 0) || ((modes!!.a!![j.toLong().toInt()] != ForcingMode.OVERRIDE) && (modes!!.a!![j.toLong().toInt()] != ForcingMode.ADD))) && (((CD!!.evap_loss_rate)!!.a!![r.toLong().toInt()] + (CD!!.seep_loss_rate)!!.a!![r.toLong().toInt()]) > 0.0)
			}
		cpp.Algo.fill_IterT_IterT_T__D((this.xnode_!!.conduit_loss)!!.begin(), (this.xnode_!!.conduit_loss)!!.end(), 0.0)
		var ci: Int = 0
		__L2@ while (ci < this.n_conduits_) {
			var j_2: Int = this.tile_uj_!!.a!![ci.toLong().toInt()]
			var r_2: Int = this.tile_crow_!!.a!![ci.toLong().toInt()]
			if (!(adjustable!!.invoke(j_2, r_2))) {
				ci++
				continue@__L2
			}
			var n1: Int = this.tile_n1_!!.a!![ci.toLong().toInt()]
			var n2: Int = this.tile_n2_!!.a!![ci.toLong().toInt()]
			var rate: Double = ((CD!!.evap_loss_rate)!!.a!![r_2.toLong().toInt()] + (CD!!.seep_loss_rate)!!.a!![r_2.toLong().toInt()]) * this.tile_barrels_d_!!.a!![ci.toLong().toInt()]
			var share: Double = if ((!((((this.node_tile_!!.a!![n1.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) && (!((((this.node_tile_!!.a!![n2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0))) 0.5 else 1.0
			if (!((((this.node_tile_!!.a!![n1.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) {
				(this.xnode_!!.conduit_loss)!!.a!![n1.toLong().toInt()] += share * rate
			}
			if (!((((this.node_tile_!!.a!![n2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) {
				(this.xnode_!!.conduit_loss)!!.a!![n2.toLong().toInt()] += share * rate
			}
			ci++
		}
		var i: Int = 0
		__L3@ while (i < this.n_nodes_) {
			(this.xnode_!!.loss_factor)!!.a!![i.toLong().toInt()] = 1.0
			var rate_2: Double = (this.xnode_!!.conduit_loss)!!.a!![i.toLong().toInt()]
			if ((rate_2 <= 0.0) || ((((this.node_tile_!!.a!![i.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) {
				i++
				continue@__L3
			}
			var area: Double = if ((nodes!!.storage_area)!!.a!![i.toLong().toInt()] > 0.0) (this.xnode_!!.new_surf_area)!!.a!![i.toLong().toInt()] else cpp.M.max_d_d((this.xnode_!!.new_surf_area)!!.a!![i.toLong().toInt()], this.min_surf_area_)
			var storage_rate: Double = (cpp.M.max_d_d(0.0, (nodes!!.old_depth)!!.a!![i.toLong().toInt()] - F_constants.FUDGE) * area) / dt
			if ((nodes!!.storage_area)!!.a!![i.toLong().toInt()] > 0.0) {
				var volume: Double = (nodes!!.old_volume)!!.a!![i.toLong().toInt()]
				var k: Int = this.csr_row_!!.a!![i.toLong().toInt()]
				__L4@ while (k < this.csr_row_!!.a!![(i + 1).toLong().toInt()]) {
					var link: Int = this.csr_link_!!.a!![k.toLong().toInt()]
					if ((((ctx!!.links)!!.type)!!.a!![link.toLong().toInt()] != LinkType.CONDUIT) || (((ctx!!.links)!!.xsect_shape)!!.a!![link.toLong().toInt()] == XsectShape.DUMMY)) {
						k++
						continue@__L4
					}
					volume -= F_dynwave.chamberPipeVolumeChange_DynamicWave(ctx, i, link, this.area1_!!.a!![link.toLong().toInt()], this.area2_!!.a!![link.toLong().toInt()], this.aa_y_prev_!!.data())
					k++
				}
				storage_rate = volume / dt
			}
			var net: Double = ((nodes!!.inflow)!!.a!![i.toLong().toInt()] - (nodes!!.outflow)!!.a!![i.toLong().toInt()]) + rate_2
			var available: Double = cpp.M.min_d_d(net + storage_rate, (net + (nodes!!.old_net_inflow)!!.a!![i.toLong().toInt()]) + (2.0 * storage_rate))
			(this.xnode_!!.loss_factor)!!.a!![i.toLong().toInt()] = cpp.M.min_d_d(1.0, cpp.M.max_d_d(0.0, available / rate_2))
			i++
		}
		var ci_2: Int = 0
		__L5@ while (ci_2 < this.n_conduits_) {
			var j_3: Int = this.tile_uj_!!.a!![ci_2.toLong().toInt()]
			var r_3: Int = this.tile_crow_!!.a!![ci_2.toLong().toInt()]
			if (!(adjustable!!.invoke(j_3, r_3))) {
				ci_2++
				continue@__L5
			}
			var n1_2: Int = this.tile_n1_!!.a!![ci_2.toLong().toInt()]
			var n2_2: Int = this.tile_n2_!!.a!![ci_2.toLong().toInt()]
			var factor: Double = cpp.M.min_d_d((this.xnode_!!.loss_factor)!!.a!![n1_2.toLong().toInt()], (this.xnode_!!.loss_factor)!!.a!![n2_2.toLong().toInt()])
			if (factor >= 1.0) {
				ci_2++
				continue@__L5
			}
			var rate_3: Double = (CD!!.evap_loss_rate)!!.a!![r_3.toLong().toInt()] + (CD!!.seep_loss_rate)!!.a!![r_3.toLong().toInt()]
			var positive: Double = (CD!!.evap_loss_rate)!!.a!![r_3.toLong().toInt()] + cpp.M.max_d_d(0.0, (CD!!.seep_loss_rate)!!.a!![r_3.toLong().toInt()])
			var scale: Double = if ((CD!!.seep_loss_rate)!!.a!![r_3.toLong().toInt()] >= 0.0) factor else (positive - (rate_3 * (1.0 - factor))) / positive
			(CD!!.evap_loss_rate)!!.a!![r_3.toLong().toInt()] *= scale
			if ((CD!!.seep_loss_rate)!!.a!![r_3.toLong().toInt()] > 0.0) {
				(CD!!.seep_loss_rate)!!.a!![r_3.toLong().toInt()] *= scale
			}
			var reduction: Double = (rate_3 * this.tile_barrels_d_!!.a!![ci_2.toLong().toInt()]) * (1.0 - factor)
			var share_2: Double = if ((!((((this.node_tile_!!.a!![n1_2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) && (!((((this.node_tile_!!.a!![n2_2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0))) 0.5 else 1.0
			if (!((((this.node_tile_!!.a!![n1_2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) {
				(nodes!!.outflow)!!.a!![n1_2.toLong().toInt()] -= share_2 * reduction
			}
			if (!((((this.node_tile_!!.a!![n2_2.toLong().toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0)) {
				(nodes!!.outflow)!!.a!![n2_2.toLong().toInt()] -= share_2 * reduction
			}
			ci_2++
		}
	}

	open fun momentumKernels(ctx: SimulationContext?, dt: Double, step: Int) {
		var links: LinkData? = ctx!!.links
		var static_slot_e: Boolean = this.surcharge_method != dynwave_SurchargeMethod.DYNAMIC_SLOT
		var do_losses: Boolean = !this.losses_all_zero_
		if (!(this.vjunc_!!.empty())) {
			this.vjPrepareIteration(ctx, dt)
		}
		var solve_conduit: FN74? = FN74 __lam1@{ ci ->
				var uci: Long = ci.toLong()
				var j: Int = this.tile_uj_!!.a!![uci.toInt()]
				var uj: Long = j.toLong()
				this.new_flow_!!.a!![uj.toInt()] = (links!!.flow)!!.a!![uj.toInt()]
				if (((this.bypassed_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
					return@__lam1
				}
				if (do_losses) {
					this.recomputeConduitLossOne(ctx, dt, ci)
				}
				this.dqdh_!!.a!![uj.toInt()] = 0.0
				if (static_slot_e) {
					var yf: Double = this.tile_y_full_!!.a!![uci.toInt()]
					var af: Double = this.tile_a_full_!!.a!![uci.toInt()]
					var rf: Double = this.tile_r_full_!!.a!![uci.toInt()]
					var wm: Double = this.tile_w_max_!!.a!![uci.toInt()]
					var shape: Short = this.tile_shape_!!.a!![uci.toInt()]
					if (this.depth1_!!.a!![uj.toInt()] >= yf) {
						this.area1_!!.a!![uj.toInt()] = af
						this.hrad1_!!.a!![uj.toInt()] = rf
					}
					if (this.depth2_!!.a!![uj.toInt()] >= yf) {
						this.area2_!!.a!![uj.toInt()] = af
					}
					if (this.depth_mid_!!.a!![uj.toInt()] >= yf) {
						this.area_mid_!!.a!![uj.toInt()] = af
						this.hrad_mid_!!.a!![uj.toInt()] = rf
					}
					if (this.depth1_!!.a!![uj.toInt()] > yf) {
						var wSlot: Double = this.getSlotWidth(this.depth1_!!.a!![uj.toInt()], yf, wm, shape)
						this.area1_!!.a!![uj.toInt()] = af + ((this.depth1_!!.a!![uj.toInt()] - yf) * wSlot)
						this.hrad1_!!.a!![uj.toInt()] = rf
					}
					if (this.depth2_!!.a!![uj.toInt()] > yf) {
						var wSlot_2: Double = this.getSlotWidth(this.depth2_!!.a!![uj.toInt()], yf, wm, shape)
						this.area2_!!.a!![uj.toInt()] = af + ((this.depth2_!!.a!![uj.toInt()] - yf) * wSlot_2)
					}
					var yMid: Double = this.depth_mid_!!.a!![uj.toInt()]
					if (yMid > yf) {
						var wSlot_3: Double = this.getSlotWidth(yMid, yf, wm, shape)
						this.area_mid_!!.a!![uj.toInt()] = af + ((yMid - yf) * wSlot_3)
						if (wSlot_3 > 0.0) {
							this.width_mid_!!.a!![uj.toInt()] = wSlot_3
						}
						this.hrad_mid_!!.a!![uj.toInt()] = rf
					}
				}
				var fc: Byte = (links!!.flow_class)!!.a!![uj.toInt()]
				var aMid: Double = this.area_mid_!!.a!![uj.toInt()]
				var yf_c: Double = this.tile_y_full_!!.a!![uci.toInt()]
				var isFull: Boolean = (this.depth1_!!.a!![uj.toInt()] >= yf_c) && (this.depth2_!!.a!![uj.toInt()] >= yf_c)
				var cat: Byte = (0).toByte()
				if ((((((fc == FlowClass.DRY) || (fc == FlowClass.UP_DRY)) || (fc == FlowClass.DN_DRY)) || (aMid <= F_constants.FUDGE)) || (((this.tile_is_closed_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0)) || ((links!!.setting)!!.a!![uj.toInt()] == 0.0)) {
					cat = dynwave_MomentumCategory.SKIP_DRY
				} else {
					if ((((this.tile_is_force_main_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0) && isFull) {
						cat = if ((ctx!!.options)!!.force_main_eqn == 1) dynwave_MomentumCategory.FORCE_MAIN_DW else dynwave_MomentumCategory.FORCE_MAIN_HW
					} else {
						if ((!(((this.tile_is_open_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0)) && isFull) {
							cat = dynwave_MomentumCategory.MANNING_CLOSED_FULL
						} else {
							if (((this.tile_is_open_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0) {
								cat = dynwave_MomentumCategory.MANNING_OPEN
							} else {
								cat = dynwave_MomentumCategory.MANNING_CLOSED_FS
							}
						}
					}
				}
				this.category_!!.a!![uj.toInt()] = cat
				__sw2@ do {
					when (cat) {
						(0).toByte() -> {
							this.processDryLink(ctx, dt, uj)
							break@__sw2
						}
						(1).toByte(), (2).toByte(), (3).toByte() -> {
							this.processManningLink(ctx, dt, step, uj, cat)
							break@__sw2
						}
						(4).toByte(), (5).toByte() -> {
							this.processForceMainLink(ctx, dt, step, uj, cat)
							break@__sw2
						}
						else -> {
							break@__sw2
						}
					}
				} while (false)
				if ((((ctx!!.nodes)!!.storage_area)!!.a!![((links!!.node1)!!.a!![uj.toInt()]).toLong().toInt()] > 0.0) || (((ctx!!.nodes)!!.storage_area)!!.a!![((links!!.node2)!!.a!![uj.toInt()]).toLong().toInt()] > 0.0)) {
					var a1: Double = this.area1_!!.a!![uj.toInt()]
					var a2: Double = this.area2_!!.a!![uj.toInt()]
					var y1: Double = cpp.M.max_d_d(0.0, ((ctx!!.nodes)!!.depth)!!.a!![((links!!.node1)!!.a!![uj.toInt()]).toLong().toInt()] - (links!!.offset1)!!.a!![uj.toInt()])
					var y2: Double = cpp.M.max_d_d(0.0, ((ctx!!.nodes)!!.depth)!!.a!![((links!!.node2)!!.a!![uj.toInt()]).toLong().toInt()] - (links!!.offset2)!!.a!![uj.toInt()])
					if (y1 < F_constants.FUDGE) {
						a1 = F_dynwave.chamberEndArea_DynamicWave(ctx, uj.toInt(), y1)
					}
					if (y2 < F_constants.FUDGE) {
						a2 = F_dynwave.chamberEndArea_DynamicWave(ctx, uj.toInt(), y2)
					}
					(links!!.volume)!!.a!![uj.toInt()] = ((0.5 * (a1 + a2)) * this.tile_links_length_!!.a!![uci.toInt()]) * this.tile_barrels_d_!!.a!![uci.toInt()]
				}
				(links!!.flow)!!.a!![uj.toInt()] = this.new_flow_!!.a!![uj.toInt()]
				(links!!.dqdh)!!.a!![uj.toInt()] = this.dqdh_!!.a!![uj.toInt()]
				return@__lam1
			}
		if ((this.unsteady_friction != 0) && (this.uf_k3 > 0.0)) {
			var ci_2: Int = 0
			__L3@ while (ci_2 < this.n_conduits_) {
				solve_conduit!!.invoke(ci_2)
				ci_2++
			}
		} else {
			var ci_3: Int = 0
			__L4@ while (ci_3 < this.n_conduits_) {
				solve_conduit!!.invoke(ci_3)
				ci_3++
			}
		}
	}

	open fun processDryLink(ctx: SimulationContext?, dt: Double, uj: Long) {
		var links: LinkData? = ctx!!.links
		var dt_g: Double = this.dt_gravity_
		var uci: Long = (this.tile_uj_to_ci_!!.a!![uj.toInt()]).toLong()
		var aMid: Double = this.area_mid_!!.a!![uj.toInt()]
		var barrels_d: Double = this.tile_barrels_d_!!.a!![uci.toInt()]
		this.area_mid_!!.a!![uj.toInt()] = 0.5 * (this.area1_!!.a!![uj.toInt()] + this.area2_!!.a!![uj.toInt()])
		this.dqdh_!!.a!![uj.toInt()] = ((dt_g * aMid) / this.tile_length_!!.a!![uci.toInt()]) * barrels_d
		this.froude_!!.a!![uj.toInt()] = 0.0
		this.new_flow_!!.a!![uj.toInt()] = 0.0
		this.q1_!!.a!![uj.toInt()] = 0.0
		var yf: Double = this.tile_y_full_!!.a!![uci.toInt()]
		(links!!.depth)!!.a!![uj.toInt()] = cpp.M.min_d_d(this.depth_mid_!!.a!![uj.toInt()], yf)
		(links!!.volume)!!.a!![uj.toInt()] = (this.area_mid_!!.a!![uj.toInt()] * this.tile_links_length_!!.a!![uci.toInt()]) * barrels_d
	}

	open fun processManningLink(ctx: SimulationContext?, dt: Double, step: Int, uj: Long, cat: Byte) {
		var links: LinkData? = ctx!!.links
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var inert_damping: Int = (ctx!!.options)!!.inertial_damping
		var dt_g: Double = this.dt_gravity_
		var is_closed_full: Boolean = cat == dynwave_MomentumCategory.MANNING_CLOSED_FULL
		var is_open_cat: Boolean = cat == dynwave_MomentumCategory.MANNING_OPEN
		var uci: Long = (this.tile_uj_to_ci_!!.a!![uj.toInt()]).toLong()
		var barrels_d: Double = this.tile_barrels_d_!!.a!![uci.toInt()]
		var length: Double = this.tile_length_!!.a!![uci.toInt()]
		var inv_len: Double = this.tile_inv_length_!!.a!![uci.toInt()]
		var aMid: Double = this.area_mid_!!.a!![uj.toInt()]
		var rMid: Double = this.hrad_mid_!!.a!![uj.toInt()]
		var qLast: Double = this.q1_!!.a!![uj.toInt()]
		var yf: Double = this.tile_y_full_!!.a!![uci.toInt()]
		var isFull: Boolean = (this.depth1_!!.a!![uj.toInt()] >= yf) && (this.depth2_!!.a!![uj.toInt()] >= yf)
		var aFull: Double = this.tile_a_full_!!.a!![uci.toInt()]
		var a1Conv: Double = F_dynwave.conveyArea_DynamicWave(this.area1_!!.a!![uj.toInt()], aFull)
		var a2Conv: Double = F_dynwave.conveyArea_DynamicWave(this.area2_!!.a!![uj.toInt()], aFull)
		var aMidConv: Double = F_dynwave.conveyArea_DynamicWave(aMid, aFull)
		var v: Double = qLast / aMidConv
		var absv: Double = cpp.SysMath.Abs_d(v)
		if (absv > F_constants.MAX_VELOCITY) {
			v = if (v > 0.0) F_constants.MAX_VELOCITY else -F_constants.MAX_VELOCITY
			absv = F_constants.MAX_VELOCITY
		}
		this.velocity_!!.a!![uj.toInt()] = v
		var fr: Double = 0.0
		var sig: Double = 0.0
		if (!is_closed_full) {
			var wMid: Double = this.width_mid_!!.a!![uj.toInt()]
			if (((links!!.flow_class)!!.a!![uj.toInt()] == FlowClass.SUBCRITICAL) && (this.wcap_dm_!!.a!![uj.toInt()] < this.depth_mid_!!.a!![uj.toInt()])) {
				var xs: XSectParams? = F_dynwave.buildXSP_DynamicWave(ctx, uj)
				wMid = F_xsect.getWofY(xs, this.depth_mid_!!.a!![uj.toInt()])
			}
			var closed_nearfull: Boolean = (!(((this.tile_is_open_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0)) && ((yf - this.depth_mid_!!.a!![uj.toInt()]) <= F_constants.FUDGE)
