					}
					if ((nodes!!.type)!!.a!![un2.toInt()] != NodeType.OUTFALL) {
						(nodes!!.inflow)!!.a!![un2.toInt()] += gain
					}
				} else {
					if (conduit_loss > 0.0) {
						if (((nodes!!.type)!!.a!![un1.toInt()] != NodeType.OUTFALL) && ((nodes!!.type)!!.a!![un2.toInt()] != NodeType.OUTFALL)) {
