			var n2_2: Int = (links!!.node2)!!.a!![uj_2.toInt()]
			var of1: Boolean = ((n1_2 >= 0) && (n1_2 < this.n_nodes_)) && ((nodes!!.type)!!.a!![n1_2.toLong().toInt()] == NodeType.OUTFALL)
			var of2: Boolean = ((n2_2 >= 0) && (n2_2 < this.n_nodes_)) && ((nodes!!.type)!!.a!![n2_2.toLong().toInt()] == NodeType.OUTFALL)
			if ((n1_2 >= 0) && (n1_2 < this.n_nodes_)) {
