				this.csr_link_!!.a!![k.toInt()] = j
				this.csr_is_n2_!!.a!![k.toInt()] = (0).toByte()
				this.csr_other_outfall_!!.a!![k.toInt()] = (if (of2) 1 else 0).toByte()
			}
			if ((n2_2 >= 0) && (n2_2 < this.n_nodes_)) {
				var k_2: Long = (cursor!!.a!![n2_2.toLong().toInt()]++).toLong()
				this.csr_link_!!.a!![k_2.toInt()] = j
				this.csr_is_n2_!!.a!![k_2.toInt()] = (1).toByte()
				this.csr_other_outfall_!!.a!![k_2.toInt()] = (if (of1) 1 else 0).toByte()
