	open fun gatherConduitNodeFlows(ctx: SimulationContext?) {
		var nodes: NodeData? = ctx!!.nodes
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var n: Int = 0
		__L1@ while (n < this.n_nodes_) {
			var un: Long = n.toLong()
			var b0: Int = this.csr_row_!!.a!![un.toInt()]
			var b1: Int = this.csr_row_!!.a!![(un + 1L).toInt()]
			if (b0 == b1) {
				n++
				continue@__L1
			}
			var self_outfall: Boolean = (((this.node_tile_!!.a!![un.toInt()] as dynwave_DWSolver_NodeTile?)!!.is_outfall).toInt() and 0xFF) != 0
			var inflow: Double = (nodes!!.inflow)!!.a!![un.toInt()]
			var outflow: Double = (nodes!!.outflow)!!.a!![un.toInt()]
			var sumdqdh: Double = (this.xnode_!!.sumdqdh)!!.a!![un.toInt()]
			var surf: Double = (this.xnode_!!.new_surf_area)!!.a!![un.toInt()]
			var k: Int = b0
			__L2@ while (k < b1) {
				var uk: Long = k.toLong()
				var uj: Long = (this.csr_link_!!.a!![uk.toInt()]).toLong()
				var at_n2: Boolean = ((this.csr_is_n2_!!.a!![uk.toInt()]).toInt() and 0xFF) != 0
				var uci: Long = (this.tile_uj_to_ci_!!.a!![uj.toInt()]).toLong()
				var q: Double = this.new_flow_!!.a!![uj.toInt()]
				if (q >= 0.0) {
					if (at_n2) {
						inflow += q
					} else {
						outflow += q
					}
				} else {
					if (at_n2) {
						outflow -= q
					} else {
						inflow -= q
					}
				}
				sumdqdh += this.dqdh_!!.a!![uj.toInt()]
				var ucr_g: Long = (this.tile_crow_!!.a!![uci.toInt()]).toLong()
				var conduit_loss: Double = ((CD!!.evap_loss_rate)!!.a!![ucr_g.toInt()] + (CD!!.seep_loss_rate)!!.a!![ucr_g.toInt()]) * this.tile_barrels_d_!!.a!![uci.toInt()]
				if (conduit_loss < 0.0) {
					var gain: Double = -conduit_loss
					if ((!self_outfall) && (!(((this.csr_other_outfall_!!.a!![uk.toInt()]).toInt() and 0xFF) != 0))) {
						gain /= 2.0
					}
					if (!self_outfall) {
						inflow += gain
					}
				} else {
					if (conduit_loss > 0.0) {
						if ((!self_outfall) && (!(((this.csr_other_outfall_!!.a!![uk.toInt()]).toInt() and 0xFF) != 0))) {
							conduit_loss /= 2.0
						}
						if (!self_outfall) {
							outflow += conduit_loss
						}
					}
				}
				var barrels: Int = cpp.Conv.D2I(this.tile_barrels_d_!!.a!![uci.toInt()])
				surf += (if (at_n2) cpp.RefD.Arr(this.surf_area2_!!.a, uj.toInt()) else cpp.RefD.Arr(this.surf_area1_!!.a, uj.toInt()))!!.get() * barrels.toDouble()
				k++
			}
			(nodes!!.inflow)!!.a!![un.toInt()] = inflow
			(nodes!!.outflow)!!.a!![un.toInt()] = outflow
			(this.xnode_!!.sumdqdh)!!.a!![un.toInt()] = sumdqdh
			(this.xnode_!!.new_surf_area)!!.a!![un.toInt()] = surf
			n++
		}
	}

	open fun computeAASkipFlags(ctx: SimulationContext?) {
