			var dy: Double = dV / denom_2
			y_new = y_old + dy
			if (!is_ponded) {
				(this.xnode_!!.old_surf_area)!!.a!![ui.toInt()] = surf_area
			}
			if (step > 0) {
				y_new = ((1.0 - this.omega) * y_last) + (this.omega * y_new)
			}
			if (is_ponded && (y_new < full_depth)) {
				y_new = full_depth - F_constants.FUDGE
			}
		} else {
			if ((!use_surcharge_dqdh) || (is_storage && ((this.xnode_!!.sumdqdh)!!.a!![ui.toInt()] == 0.0))) {
				var dy_2: Double = dV / surf_area
				y_new = y_old + dy_2
				if (!is_ponded) {
					(this.xnode_!!.old_surf_area)!!.a!![ui.toInt()] = surf_area
				}
				if (step > 0) {
					y_new = ((1.0 - this.omega) * y_last) + (this.omega * y_new)
				}
				if (is_ponded && (y_new < full_depth)) {
					y_new = full_depth - F_constants.FUDGE
				}
			} else {
				var corr: Double = 1.0
				if (t!!.degree < 0) {
					corr = 0.6
				}
				var denom_3: Double = (this.xnode_!!.sumdqdh)!!.a!![ui.toInt()]
				if ((y_last < (1.25 * yCrown)) && (yCrown > 0.0)) {
					var f_2: Double = (y_last - yCrown) / yCrown
					denom_3 += (((this.xnode_!!.old_surf_area)!!.a!![ui.toInt()] / dt) - (this.xnode_!!.sumdqdh)!!.a!![ui.toInt()]) * cpp.SysMath.Exp_d((-15.0) * f_2)
				}
				var dy_3: Double = 0.0
				if (denom_3 != 0.0) {
					dy_3 = (corr * dQ) / denom_3
				}
				y_new = y_last + dy_3
				if (y_new < yCrown) {
					y_new = yCrown - F_constants.FUDGE
				}
				if (can_pond && (y_new > full_depth)) {
					y_new = full_depth + F_constants.FUDGE
				}
			}
		}
		if (!dynwave_DWSolver.S_nf_29_done) {
			dynwave_DWSolver.S_nf_29 = null
			dynwave_DWSolver.S_nf_29_done = true
		}
		if (dynwave_DWSolver.S_nf_target_30 == (-2L)) {
			var p: cpp.CPtr? = cpp.R.getenv(cpp.R.Lit("SWMM_TRACE_NODE"))
			var tr: cpp.CPtr? = cpp.R.getenv(cpp.R.Lit("SWMM_TRACE_RSTEP"))
			var sk: cpp.CPtr? = cpp.R.getenv(cpp.R.Lit("SWMM_TRACE_SKIP"))
			dynwave_DWSolver.S_nf_target_30 = -1L
			if ((!(sk!!.get_IsNull())) && (sk!!.get(0) != 0)) {
				dynwave_DWSolver.S_nf_skip_31 = cpp.R.atol(sk)
			}
			if ((((!(p!!.get_IsNull())) && (p!!.get(0) != 0)) && (!(tr!!.get_IsNull()))) && (tr!!.get(0) != 0)) {
				var fname: cpp.CPtr? = cpp.R.Buf_i(512)
				dynwave_DWSolver.S_nf_target_30 = cpp.R.atol(p)
				cpp.R.snprintf_CPtr_ul_CPtr_oA(fname, 512L, cpp.R.Lit("%s.node%ld"), tr, dynwave_DWSolver.S_nf_target_30)
				dynwave_DWSolver.S_nf_29 = cpp.R.fopen(fname, cpp.R.Lit("w"))
				if (dynwave_DWSolver.S_nf_29 !== null) {
					cpp.R.fprintf(dynwave_DWSolver.S_nf_29, cpp.R.Lit("n,yOld,yLast,dQ,dV,surfArea,sumdqdh,surch,yNew\u000a"))
				}
			}
		}
		if ((dynwave_DWSolver.S_nf_29 !== null) && (node_idx.toLong() == dynwave_DWSolver.S_nf_target_30)) {
			dynwave_DWSolver.S_nf_count_32++
			if ((dynwave_DWSolver.S_nf_count_32.toLong() > dynwave_DWSolver.S_nf_skip_31) && (dynwave_DWSolver.S_nf_count_32.toLong() <= (dynwave_DWSolver.S_nf_skip_31 + 128L))) {
				cpp.R.fprintf(dynwave_DWSolver.S_nf_29, cpp.R.Lit("%d,%a,%a,%a,%a,%a,%a,%d,%a\u000a"), dynwave_DWSolver.S_nf_count_32, y_old, y_last, dQ, dV, surf_area, (this.xnode_!!.sumdqdh)!!.a!![ui.toInt()], if (is_surcharged) 1 else 0, y_new)
				if (dynwave_DWSolver.S_nf_count_32.toLong() >= (dynwave_DWSolver.S_nf_skip_31 + 128L)) {
					cpp.R.fclose(dynwave_DWSolver.S_nf_29)
					dynwave_DWSolver.S_nf_29 = null
				}
			}
		}
		this.commitNodeDepthState(ctx, node_idx, y_new, dV, dt)
	}

	open fun commitNodeDepthState(ctx: SimulationContext?, node_idx: Int, y_new__p: Double, dV: Double, dt: Double) {
		var y_new: Double = y_new__p
		var nodes: NodeData? = ctx!!.nodes
		var ui: Long = node_idx.toLong()
		var t: dynwave_DWSolver_NodeTile? = this.node_tile_!!.a!![ui.toInt()] as dynwave_DWSolver_NodeTile?
		y_new = cpp.M.max_d_d(y_new, 0.0)
		var is_inlet_node: Boolean = (java.lang.Long.compareUnsigned(ui, ((ctx!!.nodes)!!.is_inlet)!!.size()) < 0) && (((((ctx!!.nodes)!!.is_inlet)!!.a!![ui.toInt()]).toInt() and 0xFF) != 0)
		if ((((t!!.is_virtual).toInt() and 0xFF) != 0) && (!is_inlet_node)) {
			(nodes!!.overflow)!!.a!![ui.toInt()] = 0.0
			(nodes!!.volume)!!.a!![ui.toInt()] = 0.0
			if (dt > 0.0) {
				(this.xnode_!!.dYdT)!!.a!![ui.toInt()] = cpp.SysMath.Abs_d(y_new - (nodes!!.old_depth)!!.a!![ui.toInt()]) / dt
			}
			(nodes!!.depth)!!.a!![ui.toInt()] = y_new
			(nodes!!.head)!!.a!![ui.toInt()] = t!!.invert_elev + y_new
			return
		}
		var is_coupled: Boolean = (java.lang.Long.compareUnsigned(ui, (ctx!!.coupled_node)!!.size()) < 0) && ((((ctx!!.coupled_node)!!.a!![ui.toInt()]).toInt() and 0xFF) != 0)
		var can_pond: Boolean = ((ctx!!.options)!!.allow_ponding || is_coupled) && (t!!.ponded_area > 0.0)
		var y_max: Double = t!!.full_depth
		if (is_inlet_node && ((nodes!!.rim_depth)!!.a!![ui.toInt()] > 0.0)) {
			y_max = cpp.M.max_d_d(y_max, (nodes!!.rim_depth)!!.a!![ui.toInt()])
		}
		if (!can_pond) {
			y_max += t!!.sur_depth
		}
		(nodes!!.overflow)!!.a!![ui.toInt()] = 0.0
		if (y_new > y_max) {
			if (!can_pond) {
				(nodes!!.overflow)!!.a!![ui.toInt()] = dV / dt
				(nodes!!.volume)!!.a!![ui.toInt()] = t!!.rpt_full_volume
				y_new = y_max
			} else {
				(nodes!!.volume)!!.a!![ui.toInt()] = cpp.M.max_d_d((nodes!!.old_volume)!!.a!![ui.toInt()] + dV, t!!.rpt_full_volume)
				(nodes!!.overflow)!!.a!![ui.toInt()] = ((nodes!!.volume)!!.a!![ui.toInt()] - cpp.M.max_d_d((nodes!!.old_volume)!!.a!![ui.toInt()], t!!.rpt_full_volume)) / dt
			}
			if ((nodes!!.overflow)!!.a!![ui.toInt()] < F_constants.FUDGE) {
				(nodes!!.overflow)!!.a!![ui.toInt()] = 0.0
			}
		} else {
			if (((t!!.is_storage).toInt() and 0xFF) != 0) {
				(nodes!!.volume)!!.a!![ui.toInt()] = F_node.getVolume(nodes, node_idx, y_new, ctx!!.tables, this.unit_sys_, ctx!!.node_subtypes)
			} else {
				(nodes!!.volume)!!.a!![ui.toInt()] = if (t!!.full_depth > 0.0) t!!.rpt_full_volume * (y_new / t!!.full_depth) else 0.0
			}
		}
		if (is_inlet_node) {
			(nodes!!.volume)!!.a!![ui.toInt()] = 0.0
		}
		if (dt > 0.0) {
			(this.xnode_!!.dYdT)!!.a!![ui.toInt()] = cpp.SysMath.Abs_d(y_new - (nodes!!.old_depth)!!.a!![ui.toInt()]) / dt
		}
		(nodes!!.depth)!!.a!![ui.toInt()] = y_new
		(nodes!!.head)!!.a!![ui.toInt()] = t!!.invert_elev + y_new
	}

	open fun getLinkStep(ctx: SimulationContext?, link_idx: Int): Double {
		var uj: Long = link_idx.toLong()
		if (((ctx!!.links)!!.type)!!.a!![uj.toInt()] != LinkType.CONDUIT) {
			return 10000000000.0
		}
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var ucr: Long = ((ctx!!.link_subtypes)!!.conduit_row(link_idx)).toLong()
		var barrels: Int = cpp.M.max_i_i((CD!!.barrels)!!.a!![ucr.toInt()], 1)
		var q: Double = cpp.SysMath.Abs_d(((ctx!!.links)!!.flow)!!.a!![uj.toInt()]) / barrels.toDouble()
		if (q <= F_constants.FUDGE) {
			return 10000000000.0
		}
		var a: Double = this.area_mid_!!.a!![uj.toInt()]
		if (a <= F_constants.FUDGE) {
			return 10000000000.0
		}
		var L: Double = (CD!!.true_length)!!.a!![ucr.toInt()]
		if (L <= 0.0) {
			L = (CD!!.length)!!.a!![ucr.toInt()]
		}
		var modL: Double = (CD!!.mod_length)!!.a!![ucr.toInt()]
		var Lscale: Double = if ((L > 0.0) && (modL > 0.0)) modL / L else 1.0
		if (((this.surcharge_method == dynwave_SurchargeMethod.DYNAMIC_SLOT) && (link_idx >= 0)) && (java.lang.Long.compareUnsigned(link_idx.toLong(), this.tile_uj_to_ci_!!.size()) < 0)) {
			var ci: Int = this.tile_uj_to_ci_!!.a!![uj.toInt()]
			if (ci >= 0) {
				var uci: Long = ci.toLong()
				if (((((this.dps_!!.surcharged)!!.a!![uci.toInt()]).toInt() and 0xFF) != 0) && (L > 0.0)) {
					var v: Double = q / F_dynwave.conveyArea_DynamicWave(a, ((ctx!!.links)!!.xsect_a_full)!!.a!![uj.toInt()])
					var P: Double = cpp.M.max_d_d((this.dps_!!.P)!!.a!![uci.toInt()], 1.0)
					var c_p: Double = this.dps_config_!!.c_pT / P
					var denom: Double = cpp.SysMath.Abs_d(v) + c_p
					if (denom > 0.0) {
						return (L * Lscale) / denom
					}
				}
			}
		}
		var fr: Double = this.froude_!!.a!![uj.toInt()]
		if (fr <= 0.01) {
			return 10000000000.0
		}
		var vol: Double = ((ctx!!.links)!!.volume)!!.a!![uj.toInt()] / barrels.toDouble()
		var t: Double = vol / q
		if ((L > 0.0) && (modL > 0.0)) {
			t = (t * modL) / L
		}
		t = (t * fr) / (1.0 + fr)
		return t
	}

	open fun getSlotWidth(y: Double, y_full: Double, w_max: Double, shape: Short): Double {
		if (this.surcharge_method != dynwave_SurchargeMethod.SLOT) {
			return 0.0
		}
		if ((y_full <= 0.0) || F_dynwave.isOpenShape_DynamicWave(shape)) {
			return 0.0
		}
		var yNorm: Double = y / y_full
		if (yNorm < F_constants.SLOT_CROWN_CUTOFF) {
			return 0.0
		}
		if (yNorm > 1.78) {
			return 0.01 * w_max
		}
		return (w_max * 0.5423) * cpp.SysMath.Exp_d(-cpp.SysMath.Pow_d(yNorm, 2.4))
	}

	open fun getCrownCutoff(): Double {
		if (((this.surcharge_method == dynwave_SurchargeMethod.SLOT) || (this.surcharge_method == dynwave_SurchargeMethod.DYNAMIC_SLOT)) || (this.surcharge_method == dynwave_SurchargeMethod.TPA)) {
			return F_constants.SLOT_CROWN_CUTOFF
		}
		return F_constants.EXTRAN_CROWN_CUTOFF
	}

	open fun applyDPSGeometry(ctx: SimulationContext?) {
		var links: LinkData? = ctx!!.links
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var j: Int = this.conduit_idx_!!.a!![ci.toLong().toInt()]
			var uj: Long = j.toLong()
			var uci: Long = ci.toLong()
			if (((this.is_open_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				ci++
				continue@__L1
			}
			var yf: Double = (links!!.xsect_y_full)!!.a!![uj.toInt()]
			var af: Double = (links!!.xsect_a_full)!!.a!![uj.toInt()]
			var rf: Double = (links!!.xsect_r_full)!!.a!![uj.toInt()]
			if ((yf <= 0.0) || (af <= 0.0)) {
				ci++
				continue@__L1
			}
			var y1: Double = this.depth1_!!.a!![uj.toInt()]
			var y2: Double = this.depth2_!!.a!![uj.toInt()]
			var yMid: Double = this.depth_mid_!!.a!![uj.toInt()]
			var hs_iter: Double = if (yMid > yf) yMid - yf else 0.0
			var hs_prev: Double = (this.dps_!!.hs_prev_iter)!!.a!![uci.toInt()]
			var dhs: Double = hs_iter - hs_prev
			var P: Double = (this.dps_!!.P)!!.a!![uci.toInt()]
			var Ts: Double = ((this.dps_!!.T_s_target)!!.a!![uci.toInt()] * P) * P
			var As_new: Double = (this.dps_!!.As)!!.a!![uci.toInt()] + (Ts * dhs)
			if (As_new < 0.0) {
				As_new = 0.0
			}
			var slot_active: Boolean = (hs_iter > 0.0) || (As_new > 0.0)
			(this.dps_!!.As)!!.a!![uci.toInt()] = As_new
			(this.dps_!!.hs)!!.a!![uci.toInt()] = hs_iter
			(this.dps_!!.hs_prev_iter)!!.a!![uci.toInt()] = hs_iter
			if (!slot_active) {
				ci++
				continue@__L1
			}
			var A_total: Double = af + As_new
			this.area_mid_!!.a!![uj.toInt()] = A_total
			if (y1 > yf) {
				this.area1_!!.a!![uj.toInt()] = A_total
			}
			if (y2 > yf) {
				this.area2_!!.a!![uj.toInt()] = A_total
			}
			this.width_mid_!!.a!![uj.toInt()] = Ts
			var L: Double = this.cached_length_!!.a!![uj.toInt()]
			var slot_surf_per_end: Double = (0.25 * Ts) * L
			if (y1 > yf) {
				this.surf_area1_!!.a!![uj.toInt()] = slot_surf_per_end
			}
			if (y2 > yf) {
				this.surf_area2_!!.a!![uj.toInt()] = slot_surf_per_end
			}
			this.hrad_mid_!!.a!![uj.toInt()] = rf
			ci++
		}
	}

	open fun updateTpaLatch(ctx: SimulationContext?) {
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var kCavHead: Double = 30.0
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var uci: Long = ci.toLong()
			var j: Int = this.conduit_idx_!!.a!![uci.toInt()]
			var uj: Long = j.toLong()
			this.tpa_latch_changed_!!.a!![uci.toInt()] = (0).toByte()
			if (((this.is_open_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				this.tpa_latch_!!.a!![uci.toInt()] = (0).toByte()
				ci++
				continue@__L1
			}
			var yf: Double = (links!!.xsect_y_full)!!.a!![uj.toInt()]
			if (yf <= 0.0) {
				this.tpa_latch_!!.a!![uci.toInt()] = (0).toByte()
				ci++
				continue@__L1
			}
			var y1: Double = this.depth1_!!.a!![uj.toInt()]
			var y2: Double = this.depth2_!!.a!![uj.toInt()]
			var old: Byte = this.tpa_latch_!!.a!![uci.toInt()]
			var latched: Byte = old
			if (!((old.toInt() and 0xFF) != 0)) {
				latched = if ((y1 >= yf) && (y2 >= yf)) (1).toByte() else (0).toByte()
			} else {
				var yMid: Double = this.depth_mid_!!.a!![uj.toInt()]
				if (yMid < (yf - kCavHead)) {
					latched = (0).toByte()
				} else {
					var vented_end: FN107? = FN107 __lam2@{ n, y_end ->
				if (n < 0) {
					return@__lam2 false
				}
				var un2: Long = n.toLong()
				var sealed_: Boolean = ((java.lang.Long.compareUnsigned(un2, (nodes!!.is_virtual)!!.size()) < 0) && ((((nodes!!.is_virtual)!!.a!![un2.toInt()]).toInt() and 0xFF) != 0)) || ((java.lang.Long.compareUnsigned(un2, (nodes!!.sur_depth)!!.size()) < 0) && ((nodes!!.sur_depth)!!.a!![un2.toInt()] > 0.0))
				return@__lam2 (!sealed_) && (y_end < yf)
			}
					if (vented_end!!.invoke((links!!.node1)!!.a!![uj.toInt()], y1) || vented_end!!.invoke((links!!.node2)!!.a!![uj.toInt()], y2)) {
						latched = (0).toByte()
					}
				}
			}
			this.tpa_latch_!!.a!![uci.toInt()] = latched
			this.tpa_latch_changed_!!.a!![uci.toInt()] = if ((latched.toInt() and 0xFF) != (old.toInt() and 0xFF)) (1).toByte() else (0).toByte()
			ci++
		}
	}

	open fun applyTpaGeometry(ctx: SimulationContext?) {
		var links: LinkData? = ctx!!.links
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var uci: Long = ci.toLong()
			var j: Int = this.conduit_idx_!!.a!![uci.toInt()]
			var uj: Long = j.toLong()
			if (((this.is_open_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				ci++
				continue@__L1
			}
			var yf: Double = (links!!.xsect_y_full)!!.a!![uj.toInt()]
			var af: Double = (links!!.xsect_a_full)!!.a!![uj.toInt()]
			var rf: Double = (links!!.xsect_r_full)!!.a!![uj.toInt()]
			if ((yf <= 0.0) || (af <= 0.0)) {
				ci++
				continue@__L1
			}
			var w: Double = this.tpa_w_!!.a!![uci.toInt()]
			if (w <= 0.0) {
				ci++
				continue@__L1
			}
			var yMid: Double = this.depth_mid_!!.a!![uj.toInt()]
			var engaged: Boolean = (((this.tpa_latch_!!.a!![uci.toInt()]).toInt() and 0xFF) != 0) || (yMid >= (F_constants.SLOT_CROWN_CUTOFF * yf))
			if (!engaged) {
				ci++
				continue@__L1
			}
			var line_area: FN106? = FN106 __lam2@{ y ->
				return@__lam2 cpp.M.max_d_d(af + (w * (y - yf)), 0.05 * af)
			}
			this.area_mid_!!.a!![uj.toInt()] = line_area!!.invoke(yMid)
			this.area1_!!.a!![uj.toInt()] = line_area!!.invoke(this.depth1_!!.a!![uj.toInt()])
			this.area2_!!.a!![uj.toInt()] = line_area!!.invoke(this.depth2_!!.a!![uj.toInt()])
			this.width_mid_!!.a!![uj.toInt()] = w
			var L: Double = this.cached_length_!!.a!![uj.toInt()]
			var slot_surf_per_end: Double = (0.25 * w) * L
			this.surf_area1_!!.a!![uj.toInt()] = slot_surf_per_end
			this.surf_area2_!!.a!![uj.toInt()] = slot_surf_per_end
			this.hrad_mid_!!.a!![uj.toInt()] = rf
			ci++
		}
	}

	open fun updateDPSState(ctx: SimulationContext?, dt: Double) {
		var links: LinkData? = ctx!!.links
		this.sim_time_ += dt
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var j: Int = this.conduit_idx_!!.a!![ci.toLong().toInt()]
			var uj: Long = j.toLong()
			var uci: Long = ci.toLong()
			if (((this.is_open_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				ci++
				continue@__L1
			}
			var yf: Double = (links!!.xsect_y_full)!!.a!![uj.toInt()]
			var was_surcharged: Boolean = (((this.dps_!!.surcharged)!!.a!![uci.toInt()]).toInt() and 0xFF) != 0
			var now_surcharged: Boolean = (this.depth_mid_!!.a!![uj.toInt()] > yf) && ((this.dps_!!.As)!!.a!![uci.toInt()] > 0.0)
			if (now_surcharged && (!was_surcharged)) {
				(this.dps_!!.t_s)!!.a!![uci.toInt()] = this.sim_time_
			}
			if (now_surcharged) {
				var dt_surcharge: Double = this.sim_time_ - (this.dps_!!.t_s)!!.a!![uci.toInt()]
				(this.dps_!!.P_hat)!!.a!![uci.toInt()] = (((this.dps_!!.P_hat_0)!!.a!![uci.toInt()] - 1.0) * cpp.SysMath.Exp_d(((-10.0) * dt_surcharge) / this.dps_config_!!.r)) + 1.0
			} else {
				(this.dps_!!.P_hat)!!.a!![uci.toInt()] = (this.dps_!!.P_hat_0)!!.a!![uci.toInt()]
				(this.dps_!!.As)!!.a!![uci.toInt()] = 0.0
				(this.dps_!!.hs)!!.a!![uci.toInt()] = 0.0
				(this.dps_!!.hs_prev_iter)!!.a!![uci.toInt()] = 0.0
			}
			(this.dps_!!.surcharged)!!.a!![uci.toInt()] = (if (now_surcharged) 1 else 0).toByte()
			ci++
		}
		this.spatialSmoothP(ctx)
	}

	open fun spatialSmoothP(ctx: SimulationContext?) {
		var links: LinkData? = ctx!!.links
		var un: Long = this.n_nodes_.toLong()
		if (!dynwave_DWSolver.S_node_P_sum_33_done) {
			dynwave_DWSolver.S_node_P_sum_33 = cpp.VecD()
			dynwave_DWSolver.S_node_P_sum_33_done = true
		}
		if (!dynwave_DWSolver.S_node_P_count_34_done) {
			dynwave_DWSolver.S_node_P_count_34 = cpp.VecI()
			dynwave_DWSolver.S_node_P_count_34_done = true
		}
		dynwave_DWSolver.S_node_P_sum_33!!.assign_ul_T(un, 0.0)
		dynwave_DWSolver.S_node_P_count_34!!.assign_ul_T(un, 0)
		var ci: Int = 0
		__L1@ while (ci < this.n_conduits_) {
			var j: Int = this.conduit_idx_!!.a!![ci.toLong().toInt()]
			var uj: Long = j.toLong()
			var uci: Long = ci.toLong()
			if (((this.is_open_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0) {
				ci++
				continue@__L1
			}
			var n1: Int = (links!!.node1)!!.a!![uj.toInt()]
			var n2: Int = (links!!.node2)!!.a!![uj.toInt()]
			if ((n1 >= 0) && (n1 < this.n_nodes_)) {
				dynwave_DWSolver.S_node_P_sum_33!!.a!![n1.toLong().toInt()] += (this.dps_!!.P_hat)!!.a!![uci.toInt()]
				cpp.RefI.Cell(0)!!.set(dynwave_DWSolver.S_node_P_count_34!!.a!![n1.toLong().toInt()]++)
			}
			if ((n2 >= 0) && (n2 < this.n_nodes_)) {
				dynwave_DWSolver.S_node_P_sum_33!!.a!![n2.toLong().toInt()] += (this.dps_!!.P_hat)!!.a!![uci.toInt()]
				cpp.RefI.Cell(0)!!.set(dynwave_DWSolver.S_node_P_count_34!!.a!![n2.toLong().toInt()]++)
			}
			ci++
		}
		var ci_2: Int = 0
		__L2@ while (ci_2 < this.n_conduits_) {
			var j_2: Int = this.conduit_idx_!!.a!![ci_2.toLong().toInt()]
			var uj_2: Long = j_2.toLong()
			var uci_2: Long = ci_2.toLong()
			if (((this.is_open_!!.a!![uj_2.toInt()]).toInt() and 0xFF) != 0) {
				ci_2++
				continue@__L2
			}
			var n1_2: Int = (links!!.node1)!!.a!![uj_2.toInt()]
			var n2_2: Int = (links!!.node2)!!.a!![uj_2.toInt()]
			var P_face1: Double = (this.dps_!!.P_hat)!!.a!![uci_2.toInt()]
			var P_face2: Double = (this.dps_!!.P_hat)!!.a!![uci_2.toInt()]
			if (((n1_2 >= 0) && (n1_2 < this.n_nodes_)) && (dynwave_DWSolver.S_node_P_count_34!!.a!![n1_2.toLong().toInt()] > 0)) {
				P_face1 = dynwave_DWSolver.S_node_P_sum_33!!.a!![n1_2.toLong().toInt()] / (dynwave_DWSolver.S_node_P_count_34!!.a!![n1_2.toLong().toInt()]).toDouble()
			}
			if (((n2_2 >= 0) && (n2_2 < this.n_nodes_)) && (dynwave_DWSolver.S_node_P_count_34!!.a!![n2_2.toLong().toInt()] > 0)) {
				P_face2 = dynwave_DWSolver.S_node_P_sum_33!!.a!![n2_2.toLong().toInt()] / (dynwave_DWSolver.S_node_P_count_34!!.a!![n2_2.toLong().toInt()]).toDouble()
			}
			(this.dps_!!.P)!!.a!![uci_2.toInt()] = 0.5 * (P_face1 + P_face2)
			(this.dps_!!.P)!!.a!![uci_2.toInt()] = cpp.M.max_d_d((this.dps_!!.P)!!.a!![uci_2.toInt()], 1.0)
			ci_2++
		}
	}

