	open fun isBypassed(j: Int): Boolean {
		var uj: Long = j.toLong()
		return (java.lang.Long.compareUnsigned(uj, this.bypassed_!!.size()) < 0) && (((this.bypassed_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0)
	}

	open fun nodeSumDqdh(n: Int): cpp.RefD? {
		return cpp.RefD.Arr((this.xnode_!!.sumdqdh)!!.a, n.toLong().toInt())
	}

